/**
 * Геометрия принятых моделей набора KayKit Character Pack: Skeletons 1.1 FREE (CC0, см. assets/LICENSES.md),
 * запечённая по §6.1: без текстур, цвет — слот палитры на треугольник.
 * Позиции упакованы в 16 бит на ось в габаритах модели (min/max).
 */
export interface SkeletonModel {
  readonly tris: number;
  readonly verts: number;
  /** Габарит позы привязки: в нём квантованы позиции. */
  readonly min: readonly [number, number, number];
  readonly max: readonly [number, number, number];
  /** base64 Int16Array: 3 числа на вершину. */
  readonly pos: string;
  /** base64 Uint16Array: 3 индекса на треугольник. */
  readonly idx: string;
  /** base64 Uint8Array: индекс в SKELETON_SLOTS, один на треугольник.
   *  Вершина ломается по слоту, поэтому цвет вершины — цвет её треугольника. */
  readonly slot: string;
  /** base64 Uint8Array: до трёх костей на вершину, в порядке SKELETON_RIG. */
  readonly bone?: string;
  /** base64 Uint8Array: два веса из трёх, долями единицы; третий выводится. */
  readonly weight?: string;

  /**
   * Мировые матрицы узлов handslot.r в позе запекания и в единицах
   * набора: столбцами, как их задаёт glTF. Предмет, умноженный на матрицу,
   * оказывается в руке — там, где его держит сам набор.
   *
   * Карта, а не одно поле: рук две (§14.2), и обе живут на одном риге.
   */
  readonly hand?: Readonly<Record<string, readonly number[]>>;
}

